{"packet_id":"D085-01","doc_id":"D085","jurisdiction":"Santa Ana, CA","category":"rent_increase_limits","lifecycle":"enacted","title":"Santa Ana Rent Stabilization Ordinance annual rent cap","requirement":"A landlord may not raise residential rent by more than the lower of 3% per year or 80% of the CPI change over the most recent 12 months; if the CPI is negative, no increase is allowed.","key_value":"3% per year or 80% of CPI, whichever is lower","coverage_conditions":"All residential rental property, except buildings constructed after February 1, 1995 and mobile home spaces offered for rent after January 1, 1990.","applicability":{"conditions":[{"type":"built","role":"exempt","op":"after","date":"1995-02-01","basis":"construction"},{"type":"other","text":"mobile home spaces offered for rent after January 1, 1990 are exempt"}],"per_tenancy":null,"coverage_quotes":["The rent cap does not apply to residential buildings constructed after February 1, 1995, or to mobile home spaces offered for rent after January 1, 1990."]},"exemptions":"Residential buildings constructed after February 1, 1995; mobile home spaces offered for rent after January 1, 1990.","penalty":null,"effective_date":"2021-11-19","valid_through":null,"citation":"Rent Stabilization Ordinance","quoted_span":"Increase in residential rents are limited to the lower of 3% per year, or 80% of the percent change in the Consumer Price Index over the most recent 12-month period. If the CPI is negative, no rent increase is permitted.","interaction":null,"relations":[],"confidence":0.8,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D085-01","doc_id":"D085","jurisdiction":"Santa Ana, CA","category":"just_cause_eviction","lifecycle":"enacted","title":"Santa Ana Just Cause Eviction Ordinance","requirement":"A landlord may not end a tenancy after 30 days without just cause stated in writing, must first give the tenant a chance to cure, and for a no-fault termination must give 3 months' relocation assistance or waive the last 3 months' rent.","key_value":"3 months' relocation assistance or 3 months' rent waiver","coverage_conditions":"Residential tenancies after 30 days, except housing produced in the last 15 years, deed-restricted affordable housing, hotels, care facilities, dormitories and shared living quarters.","applicability":{"conditions":[{"type":"built_within_years","role":"exempt","years":15,"basis":"construction"},{"type":"other","text":"deed-restricted affordable housing is exempt"}],"per_tenancy":"Applies only after the first 30 days of the tenancy.","coverage_quotes":["The Just Cause Ordinance shall not apply to certain types of residential property, including housing produced in the last 15 years; deed-restricted affordable housing; hotel and transient occupancy; hospital and care facilities; dormitories; and other shared living quarters."]},"exemptions":"Housing produced in the last 15 years; deed-restricted affordable housing; hotel and transient occupancy; hospital and care facilities; dormitories; and other shared living quarters.","penalty":null,"effective_date":"2021-11-19","valid_through":null,"citation":"Just Cause Eviction Ordinance","quoted_span":"Under a no-fault just cause termination, the owner shall either provide 3 months of relocation assistance or waive payment of rent for the final 3 months of the tenancy.","interaction":null,"relations":[],"confidence":0.8,"conflict_flag":false,"conflict_note":null}
